-- Authored development dataset, not sourced from enterprise books.
-- Initialized once by MySQL on an empty dedicated volume; never run against production.
USE finance_center;
SET NAMES utf8mb4;
CREATE TABLE finance_monthly (
 period CHAR(7) NOT NULL, entity VARCHAR(100) NOT NULL,
 revenue DECIMAL(18,2) NOT NULL,
 cost DECIMAL(18,2) NOT NULL,
 opex DECIMAL(18,2) NOT NULL,
 net_profit DECIMAL(18,2) NOT NULL,
 budget_revenue DECIMAL(18,2) NOT NULL,
 budget_cost DECIMAL(18,2) NOT NULL,
 budget_opex DECIMAL(18,2) NOT NULL,
 operating_cash DECIMAL(18,2) NOT NULL,
 investing_cash DECIMAL(18,2) NOT NULL,
 financing_cash DECIMAL(18,2) NOT NULL,
 opening_cash DECIMAL(18,2) NOT NULL,
 closing_cash DECIMAL(18,2) NOT NULL,
 assets_open DECIMAL(18,2) NOT NULL,
 assets_close DECIMAL(18,2) NOT NULL,
 equity_open DECIMAL(18,2) NOT NULL,
 equity_close DECIMAL(18,2) NOT NULL,
 PRIMARY KEY(entity, period)
);
CREATE TABLE finance_receivables (
 invoice VARCHAR(100) NOT NULL, entity VARCHAR(100) NOT NULL,
 customer VARCHAR(100) NOT NULL, due_date DATE NOT NULL,
 outstanding DECIMAL(18,2) NOT NULL,
 PRIMARY KEY(entity, invoice)
);
CREATE USER IF NOT EXISTS 'finance_reader'@'%' IDENTIFIED BY 'finance_local_reader_only';
GRANT SELECT ON finance_center.* TO 'finance_reader'@'%';
